WorkflowProcessEvent.eventDescription:
function afterProcessCreate(processId){

	var attachments = hAPI.listAttachments();

	var jsonAttachments = [];
	var gson = new com.google.gson.Gson();

	for (var i = 0; i < attachments.size(); i++) {
        var attachment = attachments.get(i);

        jsonAttachments.push({
			documentId: attachment.getDocumentId(),
			fileName: attachment.getDocumentDescription(),
			version: attachment.getVersion(),
			createdAt: attachment.getCreateDate(),
			fileSize: attachment.getPhisicalFileSize()
		});
    }

	var attachmentsString = gson.toJson(jsonAttachments);

	hAPI.setCardValue("anexosNS", attachmentsString);
}

function servicetask53(attempt, message) {
try {
log.info("### servicetask53 - INICIO");
var constraints = [];
// ===================================================== // HELPERS // ===================================================== function addConstraint(fieldName, value) {
if (value == null) { value = ""; }
constraints.push( DatasetFactory.createConstraint( fieldName, String(value), String(value), ConstraintType.MUST ) ); }
// ===================================================== // CAMPOS SIMPLES // =====================================================
var simpleFields = [
"timelineNS", "decisaoSuperiorImediato", "decisaoAvaliarProjeto", "payloadJsonGLPI", "forcarErroGLPI",
"titulodoprojetoNS", "ColigadaNS", "areaUnidadeNS", "centrodecustoNS", "centrodecustoNomeNS", "aprovadorSuperiorImedNS", "patrocinadorNS", "projetoPrivadoNS", "projetoPrivadoAPTI", "projetoPrivadoAtualGP", "participantesProjetoNS", "solicitanteNomeNS", "solicitanteColleagueIdNS", "objetivodoprojetoNS", "problemaOportunidadeNS", "beneficiosesperadosNS", "alinhadobevapNS", "prioridadeNS", "escopoinicialNS", "foradeescopoNS", "dependenciasNS", "anexosNS", "observacoesadicionaisNS",
"visibilidadetecnicaAPTI", "alternativasconsideradasAPTI", "esforcoestimadohorasAPTI", "esforcoestimadopontosAPTI", "dependenciastecnicasAPTI", "observacoesdaanaliseAPTI", "objetivoClaramenteDefinidoAPTI", "escopoBemDelimitadoAPTI", "documentacaoTecnicaAdeqAPTI", "patrocinadoridentificadoAPTI", "alinhEstratConfAPTI", "recursosTecDispAPTI", "anexosessenciaispresentesAPTI",
"disponibilidadedaEquipeSI", "recursosNecessariosAreaSI", "conflitosdeAgendaSI", "prioridadeparaaAreaSI", "observacoesdoGestorSI", "equipepossuiDisponibilidadeSI", "recursosNecessIdentSI", "naoHaConflitosCriticosSI", "projetoAlinhadoPrioridadesSI",
"execucaoProjetoTITT", "motivoDecisaoCategoriaTITT", "motivoDecisaoDescricaoTITT", "disponibilidadedaEquipeTITT", "dataDesejadaInicioTITT",
"fornecedorRecomendadoTITT", "codfornTITT", "tipoContratacaoTITT", "justifExecucaoExtTITT", "anexosApoioTITT",
"escopoProjClaroDetTITT", "estimativasCustoPrazoRegTITT", "anexosEssenciaisPresentesTITT", "decisaoExecucaoDocumentadaTITT", "riscosDependenciasMapeadosTITT",
"dataHoraCAP", "anotacoesCAP", "anexarAtaReuniaoCAP", "decisaocomite1", "justificativacomite1", "categoriajusticomite1",
"nomeFornecedorTIPC", "codFornecedorTIPC", "cnpjTIPC", "nomeContatoTIPC", "emailTIPC", "telefoneTIPC", "nomeContato2TIPC", "email2TIPC", "telefone2TIPC", "numeroRefPropostaTIPC", "vigenciaDiasTIPC", "valortotalTIPC", "moedaTIPC", "simboloMoedaTIPC", "prazoEstimadoTIPC", "condicaoPagamentoTIPC", "codigoCondicaoPagamentoTIPC", "escopoResumidoTIPC",
"anexosPropostaTIPC",
"escopoClaroDetalhadoTIPC", "impostosTaxasInclusosTIPC", "prazosEntregaDefinidosTIPC", "garantiasSlaEspecificadosTIPC", "vigenciaPropostaConfirmadaTIPC", "documentosAnexCompTIPC",
"decisaoTIPC", "justificativaTIPC", "categoriajustiTIPC",
"observacoesNegociacaoSAP", "liConcordoPropostaComercialSAP", "decisaoPropostaSAP", "justificativaPropostaSAP", "categoriajustiPropostaSAP",
"capexGCC", "valorCapexGCC", "naturezaCapexGCC",
"opexGCC", "valorOpexGCC", "naturezaOpexGCC",
"competenciaGCC", "observacoesNegociacaoGCC", "decisaoGCC", "justificativaGCC", "categoriaJustificativaGCC",
"dataHoraACP", "anotacoesACP", "anexarAtaReuniaoACP", "decisaocomite2", "justificativacomite2", "categoriajusticomite2",
"tipoContratacaoCRC", "numeroPedidoContratoCRC", "dataEmissaoCRC", "inicioVigenciaCRC", "fimVigenciaCRC", "condicaoPagamentoCRC", "centroCustoCRC", "contaContabilCRC", "escopoAcordadoCRC", "slaGarantiaCRC", "multasRescisaoCRC", "pessoaJuridicaRegularCRC", "certidoesNegativasCRC", "lgpdCRC", "analiseSegurancaCRC", "seguroResponsabilidadeCRC", "anexosCRC",
"escolhercondicaopagamentoCRC", "quantasVezesCondicaoCRC", "periodoEmDiasCondicaoCRC", "escolherparcelasCRC",
"valorFinalCRC", "impostosEncargosCRC", "capexCRC", "opexCRC",
"decisaoCRC", "justificativaCRC", "categoriajustiCRC",
"decisaoCorrecao", "justificativaCorrecao", "categoriajustiCorrecao",
"idGLPI", "codigoglpi", "statusIntegracaoGLPI", "mensagemErroGLPI" ];
for (var i = 0; i < simpleFields.length; i++) {
var fieldName = simpleFields[i]; var value = hAPI.getCardValue(fieldName);
addConstraint(fieldName, value); }
// ===================================================== // TABELAS PAI X FILHO // =====================================================
var childTables = {
"tblBeneficiosEsperadosNS": [ "beneficioEsperadoNS" ],
"tblObjetivosEstrategicosNS": [ "descricaoobjetivoNS" ],
"tblRiscosIniciaisNS": [ "riscoPotencialNS" ],
"tblStakeholdersNS": [ "valorstakeholdersNS" ],
"tblRiscosIdentificadosAPTI": [ "nivelRiscoAPTI", "descricaoRiscoAPTI" ],
"tblRiscosIdentificadosTITT": [ "tituloRiscoTITT", "descricaoRiscoTITT", "mitigacaoRiscoTITT", "planoBRiscoTITT", "nivelRiscoTITT", "impactoRiscoTITT", "probabilidadeRiscoTITT" ],
"tblDependenciasTITT": [ "tituloDependenciaTITT", "statusDependenciaTITT", "responsavelDependenciaTITT", "mitigacaoDependenciaTITT", "planoBDependenciaTITT" ],
"tblParticipantesCAP": [ "nomeParticipanteCAP" ],
"tblItensServicosTIPC": [ "descricaoItemServicoTIPC", "quantidadeItemServicoTIPC", "valorUnitarioItemServicoTIPC", "totalItemServicoTIPC" ],
"tblRiscosIniciaisTIPC": [ "tituloRiscoTIPC", "descricaoRiscoTIPC", "mitigacaoRiscoTIPC", "planoBRiscoTIPC", "nivelRiscoTIPC", "impactoRiscoTIPC", "probabilidadeRiscoTIPC", "riscoPotencialTIPC" ],
"tblPreRequisitosTIPC": [ "tituloPreRequisitoTIPC", "statusPreRequisitoTIPC", "responsavelPreRequisitoTIPC", "mitigacaoPreRequisitoTIPC", "planoBPreRequisitoTIPC", "preRequisitoTIPC" ],
"tblNaturezaCustoCapexGCC": [ "centroCustoCapexGCC", "contaContabilCapexGCC", "porcentagemCapexGCC", "saldoCapexGCC", "saldoAposCompromissoCapexGCC" ],
"tblNaturezaCustoOpexGCC": [ "centroCustoOpexGCC", "contaContabilOpexGCC", "porcentagemOpexGCC", "saldoOpexGCC", "saldoAposCompromissoOpexGCC" ],
"tblParticipantesACP": [ "nomeParticipanteACP" ] };
for (var tableName in childTables) {
var indexes = hAPI.getChildrenIndexes(tableName);
if (!indexes || indexes.length == 0) { continue; }
for (var x = 0; x < indexes.length; x++) {
var idx = indexes[x];
var fieldsTable = childTables[tableName];
for (var y = 0; y < fieldsTable.length; y++) {
var field = fieldsTable[y]; var completeField = field + "___" + idx;
var fieldValue = hAPI.getCardValue(completeField);
addConstraint( completeField, fieldValue ); } } }
log.info("### servicetask53 - TOTAL CONSTRAINTS: " + constraints.length);
// ===================================================== // START PROCESS // =====================================================
// var startProcessUser = "e6cfab79-5cf3-4350-a789-bdfb89ebc741"; // PRD var startProcessUser = "14cdc0c0-a710-4412-81dd-d94fe3abe00a"; // QA
var fields = [ startProcessUser, "ProcessDesenvolvimentoProjetos", "0", getValue("WKCompany") + "", "", "true" ];
var ds = DatasetFactory.getDataset( "dsStartProcess", fields, constraints, null );
if (ds == null || ds.rowsCount == 0) { throw "Dataset dsStartProcess nao retornou dados."; }
var status = ds.getValue(0, "status"); var numSolicitacao = ds.getValue(0, "numSolicitacao");
log.info("### servicetask53 - STATUS: " + status); log.info("### servicetask53 - NOVO PROCESSO: " + numSolicitacao);
if (status != "OK") { throw "Erro ao iniciar processo."; }
return true;
} catch (e) {
log.error("### servicetask53 - ERRO: " + e);
throw e; } }

function afterStateLeave(sequenceId) {
    var atividade = getValue("WKNumState");

    var targetFieldByActivity = {
        "15": "anexosNS",
        "26": "anexosApoioTITT",
        "36": "anexarAtaReuniaoCAP",
        "38": "anexosPropostaTIPC",
        "61": "anexarAtaReuniaoACP",
        "66": "anexosCRC"
    };

    var targetField = targetFieldByActivity[String(atividade)];
    if (!targetField) return;

    try {
        var gson = new com.google.gson.Gson();
        var attachments = hAPI.listAttachments();

        function safeParseArray(text) {
            var raw = String(text || "").trim();
            if (!raw) return [];

            try {
                var parsed = JSON.parse(raw);
                return (parsed && parsed.length !== undefined) ? parsed : [];
            } catch (e) {
                // fallback para casos onde JSON parse falhe por formatação
                try {
                    var parsed2 = gson.fromJson(raw, java.lang.Object);
                    return (parsed2 && parsed2.length !== undefined) ? parsed2 : [];
                } catch (e2) {
                    return [];
                }
            }
        }

        function extractDocumentIds(arr) {
            var ids = {};
            for (var i = 0; i < arr.length; i++) {
                var item = arr[i];
                var docId = item ? (item.documentId || item.documentID || item.id) : null;
                if (docId !== null && docId !== undefined) {
                    ids[String(docId)] = true;
                }
            }
            return ids;
        }

        // Excluir anexos já salvos em qualquer campo de anexo para evitar duplicidade cruzada.
        var attachmentFields = [
            "anexosNS",
            "anexosApoioTITT",
            "anexarAtaReuniaoCAP",
            "anexosPropostaTIPC",
            "anexarAtaReuniaoACP",
            "anexosCRC"
        ];

        var excludedIds = {};
        for (var f = 0; f < attachmentFields.length; f++) {
            var fieldName = attachmentFields[f];
            if (fieldName === targetField) {
                continue;
            }
            var jsonText = String(hAPI.getCardValue(fieldName) || "");
            var fieldIds = extractDocumentIds(safeParseArray(jsonText));

            for (var idKey in fieldIds) {
                if (fieldIds.hasOwnProperty(idKey)) {
                    excludedIds[idKey] = true;
                }
            }
        }

        var jsonAttachments = [];

        for (var j = 0; j < attachments.size(); j++) {
            var attachment = attachments.get(j);
            var documentId = String(attachment.getDocumentId());

            // só pega anexos que ainda nao foram salvos em outros campos de anexo
            if (excludedIds[documentId] === true) continue;

            jsonAttachments.push({
                documentId: attachment.getDocumentId(),
                fileName: attachment.getDocumentDescription(),
                version: attachment.getVersion(),
                createdAt: attachment.getCreateDate(),
                fileSize: attachment.getPhisicalFileSize()
            });
        }

        var attachmentsString = gson.toJson(jsonAttachments);

        hAPI.setCardValue(targetField, attachmentsString);
        log.info("[afterStateLeave] Atividade " + atividade + ": anexos novos salvos em " + targetField + " = " + jsonAttachments.length);
    } catch (error) {
        log.error("[afterStateLeave] Erro ao capturar anexos (atividade " + atividade + "): " + error);
    }
}

function servicetask29(attempt, message) {
    var FIELD_ID_GLPI = 'idGLPI';
    var FIELD_STATUS = 'statusIntegracaoGLPI';
    var FIELD_ERROR = 'mensagemErroGLPI';
    var FIELD_PAYLOAD = 'payloadJsonGLPI'; // <--- 1. DECLARAMOS O CAMPO AQUI

    // ? 1ª TRAVA: Bloqueia as retentativas invisíveis (Assíncronas) do Fluig por instabilidade
    if (attempt > 1) {
        log.warn("=== BLOQUEANDO EXECUCAO DUPLICADA NO GLPI === Tentativa: " + attempt);
        throw "A integração demorou a responder na primeira tentativa. Verifique manualmente no GLPI antes de prosseguir."; 
    }

    try {
        assertForcedGlpiTestError(FIELD_STATUS, FIELD_ERROR);

        var existingIdGlpi = asText(hAPI.getCardValue(FIELD_ID_GLPI));
        
        // Removemos a 2ª Trava. Se chegou aqui de novo e tem ID, ele VAI fazer o Update (PUT).

        setCardValueSafe(FIELD_STATUS, 'PROCESSANDO');
        setCardValueSafe(FIELD_ERROR, '');

        var sessionToken = getGlpiNovoSessionToken();
        var isUpdate = !!existingIdGlpi;

        // 1. Descobrir e-mail do solicitante
        var solicitanteId = getCardValueSafe('solicitanteColleagueIdNS');
        var emailUsuario = getUserEmailByColleagueId(solicitanteId);
        if (!emailUsuario) {
            throw "E-mail do solicitante não encontrado no Fluig.";
        }

        // 2. Descobrir o ID do Usuário no GLPI
        var glpiUserId = getGlpiUserIdByEmail(sessionToken, emailUsuario);
        if (!glpiUserId) {
            throw "Usuário com e-mail " + emailUsuario + " não encontrado no GLPI.";
        }

        // 3. Descobrir o ID do Grupo do Usuário no GLPI
        var glpiGroupId = getGlpiGroupIdByUserId(sessionToken, glpiUserId);

        // 4. Montar o Payload dinâmico usando o código já salvo no formulário
        var projectInput = buildGlpiProjectInput(isUpdate, glpiUserId, glpiGroupId);

        // <--- 2. SALVA O PAYLOAD NA TELA (EM FORMATO TEXTO) PARA USO FUTURO --->
        setCardValueSafe(FIELD_PAYLOAD, JSON.stringify(projectInput));

        // 5. Enviar para o dataset de Upsert (criação/atualização)
        var upsertResult = upsertGlpiProject(sessionToken, projectInput, existingIdGlpi);

        if (!upsertResult.ok) {
            throw upsertResult.message;
        }

        // Só salva o ID se for uma criação nova (POST)
        if (!isUpdate && upsertResult.glpiId) {
            setCardValueSafe(FIELD_ID_GLPI, upsertResult.glpiId);
        }

        setCardValueSafe(FIELD_STATUS, 'OK');
        setCardValueSafe(FIELD_ERROR, '');
        return true;
    } catch (e) {
        var errMsg = formatErrorMessage(e);
        setCardValueSafe(FIELD_STATUS, 'ERROR');
        setCardValueSafe(FIELD_ERROR, errMsg);
        throw errMsg;
    }
}
// ==========================================
// FUNÇÕES DE BUSCA (FLUIG E GLPI)
// ==========================================

function getUserEmailByColleagueId(colleagueId) {
    if (!colleagueId) return "";
    var c1 = DatasetFactory.createConstraint("colleaguePK.colleagueId", colleagueId, colleagueId, ConstraintType.MUST);
    var ds = DatasetFactory.getDataset("colleague", null, [c1], null);
    
    if (ds && ds.rowsCount > 0) {
        return asText(ds.getValue(0, "mail"));
    }
    return "";
}

function getGlpiUserIdByEmail(sessionToken, email) {
    var endpoint = "/apirest.php/search/User?criteria[0][field]=5&criteria[0][searchtype]=contains&criteria[0][value]=" + email + "&forcedisplay[0]=2";
    var resultStr = callGlpiGetDataset(sessionToken, endpoint);
    
    try {
        var json = JSON.parse(resultStr);
        if (json.data && json.data.length > 0) {
            // Pega o ID (campo "2") do primeiro registro encontrado
            return json.data[0]["2"]; 
        }
    } catch (e) {
        log.error("Erro ao parsear retorno do GLPI para Usuario: " + e);
    }
    return 0;
}

function getGlpiGroupIdByUserId(sessionToken, userId) {
    if (!userId || userId === 0) return 0;
    
    var endpoint = "/apirest.php/User/" + userId + "/Group_User";
    var resultStr = callGlpiGetDataset(sessionToken, endpoint);
    
    try {
        var json = JSON.parse(resultStr);
        if (Array.isArray(json) && json.length > 0) {
            // Retorna o groups_id do primeiro objeto do array
            return json[0].groups_id;
        }
    } catch (e) {
        log.error("Erro ao parsear retorno do GLPI para Grupo: " + e);
    }
    return 0;
}

function callGlpiGetDataset(sessionToken, endpoint) {
    var constraints = [];
    constraints.push(DatasetFactory.createConstraint('sessionToken', sessionToken, sessionToken, ConstraintType.MUST));
    constraints.push(DatasetFactory.createConstraint('endpoint', endpoint, endpoint, ConstraintType.MUST));
    
    var ds = DatasetFactory.getDataset('dsGLPINovoGet', null, constraints, null);
    if (ds && ds.rowsCount > 0) {
        var status = asText(ds.getValue(0, "status"));
        if (status === "OK") {
            return asText(ds.getValue(0, "response_data"));
        } else {
            throw asText(ds.getValue(0, "message"));
        }
    }
    throw "Dataset dsGLPINovoGet não retornou dados.";
}

// ==========================================
// MONTAGEM DO PAYLOAD
// ==========================================

function buildGlpiProjectInput(isUpdate, glpiUserId, glpiGroupId) {
    var title = getCardValueSafe('titulodoprojetoNS');
    var objective = getCardValueSafe('objetivodoprojetoNS');
    var comments = getCardValueSafe('observacoesadicionaisNS');
    var prioridade = getCardValueSafe('prioridadeNS');
    
    var now = getCurrentDateTime();
    var mappedPriority = mapPrioridade(prioridade);
    var projectCode = getCardValueSafe('codigoglpi');

    // Se não existir código no formulário, geramos aqui usando a mesma regra
    // de safra (início 01/04) no formato PRJ-{YYstart}{YYend}-{processId}
    if (!projectCode) {
        var procId = '';
        try {
            procId = getProcessInstanceId();
        } catch (e) {
            procId = '';
        }
        projectCode = buildProjectCode(procId, null);
        if (projectCode) {
            setCardValueSafe('codigoglpi', projectCode);
        } else {
            throw "Campo codigoglpi não preenchido no formulário e não foi possível gerar automaticamente.";
        }
    }

    var payload = {
        name: title || "Projeto sem Titulo",
        code: projectCode,
        priority: mappedPriority,
        entities_id: 1,
        is_recursive: 0,
        projects_id: 0,
        projectstates_id: 0,
        projecttypes_id: 0,
        users_id: parseInt(glpiUserId, 10) || 0,
        groups_id: parseInt(glpiGroupId, 10) || 0,
        date_mod: now,
        plan_start_date: "",
        plan_end_date: "",
        real_start_date: "",
        real_end_date: "",
        percent_done: 0,
        auto_percent_done: 0,
        show_on_global_gantt: 0,
        content: objective,
        comment: comments,
        is_deleted: 0,
        projecttemplates_id: 0,
        is_template: 0
    };

    // Se for criação (POST), adicionamos as datas iniciais
    if (!isUpdate) {
        payload.date = now;
        payload.date_creation = now;
    }

    return payload;
}

function mapPrioridade(prioridadeValue) {
    var normalized = String(prioridadeValue || '').toLowerCase().trim();
    
    if (normalized === 'critico') {
        return 6;
    } else if (normalized === 'estrategico') {
        return 3;
    } else if (normalized === 'operacional') {
        return 2;
    }
    
    // fallback: prioridade normal
    return 1;
}

function getCurrentDateTime() {
    var date = new Date();
    var yyyy = date.getFullYear();
    var mm = padZero(date.getMonth() + 1);
    var dd = padZero(date.getDate());
    var hh = padZero(date.getHours());
    var min = padZero(date.getMinutes());
    var ss = padZero(date.getSeconds());
    return yyyy + "-" + mm + "-" + dd + " " + hh + ":" + min + ":" + ss;
}

function padZero(num) {
    return num < 10 ? "0" + num : num;
}

function getGlpiNovoSessionToken() {
    var ds = DatasetFactory.getDataset('dsGLPINovoInitSession', null, null, null);
    ensureDatasetHasRow(ds, 'dsGLPINovoInitSession');
    var status = asText(ds.getValue(0, 'status'));
    var token = asText(ds.getValue(0, 'session_token'));
    if (status !== 'OK' || !token) {
        throw asText(ds.getValue(0, 'message')) || 'Falha ao obter session_token';
    }
    return token;
}

function upsertGlpiProject(sessionToken, projectInput, existingIdGlpi) {
    var constraints = [];
    constraints.push(DatasetFactory.createConstraint('sessionToken', sessionToken, sessionToken, ConstraintType.MUST));
    constraints.push(DatasetFactory.createConstraint('itemtype', 'Project', 'Project', ConstraintType.MUST));
    constraints.push(DatasetFactory.createConstraint('bodyJson', JSON.stringify(projectInput), JSON.stringify(projectInput), ConstraintType.MUST));

    var method = existingIdGlpi ? 'PUT' : 'POST';
    constraints.push(DatasetFactory.createConstraint('method', method, method, ConstraintType.MUST));

    if (existingIdGlpi) {
        constraints.push(DatasetFactory.createConstraint('id', existingIdGlpi, existingIdGlpi, ConstraintType.MUST));
    }

    var ds = DatasetFactory.getDataset('dsGLPINovoProjectUpsert', null, constraints, null);
    ensureDatasetHasRow(ds, 'dsGLPINovoProjectUpsert');

    var status = asText(ds.getValue(0, 'status'));
    return {
        ok: status === 'OK',
        glpiId: asText(ds.getValue(0, 'glpi_id')),
        message: asText(ds.getValue(0, 'message')) || 'Falha ao integrar com GLPI.'
    };
}

function getCardValueSafe(fieldName) {
    try {
        return asText(hAPI.getCardValue(fieldName));
    } catch (e) {
        return '';
    }
}

function assertForcedGlpiTestError(statusField, errorField, responseField) {
    var forceError = '';
    try {
        forceError = asText(hAPI.getCardValue('forcarErroGLPI'));
    } catch (e) {
        forceError = '';
    }

    if (forceError === '1') {
        var message = 'Erro GLPI forcado para teste (forcarErroGLPI=1).';
        if (statusField) {
            setCardValueSafe(statusField, 'ERROR');
        }
        if (errorField) {
            setCardValueSafe(errorField, message);
        }
        if (responseField) {
            setCardValueSafe(responseField, message);
        }
        log.warn(message);
        throw message;
    }
}

function setCardValueSafe(fieldName, value) {
    try {
        hAPI.setCardValue(fieldName, String(value == null ? '' : value));
    } catch (e) {}
}

function ensureDatasetHasRow(ds, datasetName) {
    var count = 0;
    try { count = ds.getRowCount(); } catch (e) {
        try { count = ds.rowsCount; } catch (e2) { count = 0; }
    }
    if (!count || count < 1) throw 'Dataset ' + datasetName + ' nao retornou linhas.';
}

function asText(value) {
    if (value === null || value === undefined) return '';
    return String(value).replace(/^\s+|\s+$/g, '');
}

function formatErrorMessage(error) {
    var raw = String(error || 'Erro desconhecido');
    if (raw.indexOf('PKIX') >= 0 || raw.indexOf('SSL') >= 0) {
        return 'Falha SSL (PKIX): certificado nao confiavel.';
    }
    return raw;
}

// Obtém o ID da solicitação / processo (tenta campo do formulário, depois WorkflowAPI)
function getProcessInstanceId() {
    try {
        var nrSolicitacao = hAPI.getCardValue('NR_SOLICITACAO');
        if (nrSolicitacao) {
            return asText(nrSolicitacao);
        }
    } catch (e) {}
    
    try {
        if (typeof WorkflowAPI !== 'undefined' && WorkflowAPI.getProcessInstanceId) {
            return asText(WorkflowAPI.getProcessInstanceId());
        }
    } catch (e) {}
    
    throw 'Não foi possível obter o ID da solicitação (processInstanceId)';
}

// Gera código do projeto com base na safra (início 01/04): PRJ-{YYstart}{YYend}-{processId}
function buildProjectCode(processInstanceId, referenceDate) {
    var pid = String(processInstanceId || '').replace(/^\s+|\s+$/g, '');
    if (!pid) return '';

    var ref = referenceDate || new Date().toISOString();
    var dt = new Date(ref);
    if (isNaN(dt.getTime())) dt = new Date();
    var year = dt.getFullYear();
    var month = dt.getMonth() + 1;

    var startYear = (month >= 4) ? year : (year - 1);
    var endYear = startYear + 1;
    var startYY = String(startYear).slice(-2);
    var endYY = String(endYear).slice(-2);
    var safraCode = startYY + endYY;

    var paddedProcessId = String(pid || '0').replace(/^0+/, '').padStart(4, '0');
    return 'PRJ-' + safraCode + '-' + paddedProcessId;
}

var GP_NOTIFY_TEMPLATE = "tpl_gp_tarefa_pendente";
// var GP_NOTIFY_SENDER = "b1c70351e76b4a59b8f12f596389cbb5"; // PROD
var GP_NOTIFY_SENDER = "e6cfab79-5cf3-4350-a789-bdfb89ebc741"; // QA
var GP_WIDGET_URL = "https://fluig.bevap.com.br:8443/portal/p/1/bevap-gestao-projetos";
var GP_NOTIFY_FIXED_RECIPIENTS = [
    { name: "Vinicius Nogueira", receiver: "vinicius.nogueira@vflows.com.br", external: true }
];

function afterTaskCreate(colleagueId) {
    try {
        var activity = text(getValue("WKNextState"));
        var config = getNotifyConfig(activity);
        if (!config) return;

        var context = buildContext(activity, config);
        var recipients = uniqueRecipients(GP_NOTIFY_FIXED_RECIPIENTS.concat(getRecipients(config)));

        for (var i = 0; i < recipients.length; i++) {
            sendNotification(context, recipients[i]);
        }
    } catch (e) {
        log.error("[GP][afterTaskCreate] Erro ao notificar tarefa pendente: " + e);
    }
}

function getNotifyConfig(activity) {
    var configs = {
        "5": { name: "TI - Avaliar Projeto", type: "group", target: "TI", label: "TI", route: "evaluateProject" },
        "15": { name: "Corrigir Solicitação", type: "user", field: "solicitanteColleagueIdNS", correction: true, route: "correction" },
        "19": { name: "Superior Imediato - Aprovar Projeto", type: "user", field: "aprovadorSuperiorImedNS", route: "immediateApproval" },
        "26": { name: "TI - Triagem Técnica", type: "group", target: "TI", label: "TI", route: "technicalTriage" },
        "36": { name: "Comitê - Aprovar Projeto", type: "group", target: "COMITE_GP", label: "Comitê de Gestão de Projetos", route: "committeeApproval" },
        "38": { name: "TI - Anexar Proposta Comercial", type: "group", target: "TI", label: "TI", route: "commercialProposal" },
        "40": { name: "Solicitante - Aprovar Proposta", type: "user", field: "solicitanteColleagueIdNS", route: "requesterProposalApproval" },
        "54": { name: "Gerente do Centro de Custo - Aprovar Custo Projeto", type: "user", field: "aprovadorSuperiorImedNS", route: "gccCostApproval" },
        "61": { name: "Comitê - Aprovar Custo Projeto", type: "group", target: "COMITE_GP", label: "Comitê de Gestão de Projetos", route: "committeeCostApproval" },
        "66": { name: "Compras - Realizar Contratação", type: "group", target: "COMPRAS", label: "Compras", route: "purchaseContracting" }
    };

    return configs[String(activity)] || null;
}

function buildContext(activity, config) {
    var processId = text(getValue("WKNumProces"));
    var documentId = text(getValue("WKCardId"));
    var link = GP_WIDGET_URL + "#" + config.route + "?processInstanceId=" + processId;

    if (documentId) {
        link += "&documentId=" + documentId;
    }

    return {
        activity: activity,
        activityName: config.name,
        correction: config.correction === true,
        groupLabel: config.label || "",
        isGroup: config.type === "group",
        processId: processId,
        projectCode: cardValue("codigoglpi") || ("Processo " + processId),
        projectTitle: cardValue("titulodoprojetoNS") || "Projeto sem título",
        link: link
    };
}

function getRecipients(config) {
    if (config.type === "user") {
        return userRecipient(cardValue(config.field));
    }

    if (config.type === "group") {
        return groupRecipients(config.target);
    }

    return [];
}

function userRecipient(colleagueId) {
    var user = getColleague(colleagueId);
    return user.receiver ? [user] : [];
}

function groupRecipients(groupId) {
    var rows = datasetRows("colleagueGroup", "colleagueGroupPK.groupId", groupId);
    var recipients = [];
    var seen = {};

    for (var i = 0; i < rows.length; i++) {
        var colleagueId = rows[i]("colleagueGroupPK.colleagueId") || rows[i]("colleagueId");
        var user = getColleague(colleagueId);

        if (user.receiver && !seen[user.receiver]) {
            seen[user.receiver] = true;
            recipients.push(user);
        }
    }

    return recipients;
}

function getColleague(colleagueId) {
    var id = text(colleagueId);
    var rows = id ? datasetRows("colleague", "colleaguePK.colleagueId", id) : [];

    if (rows.length === 0) {
        return { colleagueId: id, name: id, receiver: "" };
    }

    var email = rows[0]("mail") || rows[0]("email");

    return {
        colleagueId: id,
        name: rows[0]("colleagueName") || rows[0]("name") || id,
        receiver: email,
        email: email
    };
}

function uniqueRecipients(recipients) {
    var unique = [];
    var seen = {};

    for (var i = 0; i < recipients.length; i++) {
        var receiver = text(recipients[i].receiver);
        if (receiver && !seen[receiver]) {
            seen[receiver] = true;
            unique.push(recipients[i]);
        }
    }

    return unique;
}

function sendNotification(context, recipient) {
    var params = new java.util.HashMap();
    var message = buildMessage(context, recipient.name);
    var destinations = new java.util.ArrayList();

    destinations.add(recipient.receiver);

    params.put("subject", "[" + context.projectCode + "] Gestão de Projetos - Tarefa Pendente");
    params.put("htmlBody",
        "<p style=\"margin:0 0 24px 0;\">" + escapeHtml(message) + "</p>" +
        "<p style=\"margin:0;text-align:center;\"><a href=\"" + escapeHtml(context.link) + "\" style=\"background-color:#007bff;color:#ffffff;padding:12px 25px;text-decoration:none;border-radius:5px;font-size:16px;display:inline-block;\">Clique aqui para acessar a solicitação</a></p>");

    log.info("[GP][afterTaskCreate] notifier.notify destino=" + recipient.receiver +
        ", tipo=" + (recipient.external ? "email" : "usuario") +
        ", processo=" + context.processId +
        ", atividade=" + context.activity);

    notifier.notify(GP_NOTIFY_SENDER, GP_NOTIFY_TEMPLATE, params, destinations, "text/html");
}

function buildMessage(context, name) {
    if (context.correction) {
        return "Olá " + name + ", a solicitação " + context.projectCode +
            " retornou para correção e existe uma tarefa pendente sob sua responsabilidade. Favor verificar.";
    }

    if (context.isGroup) {
        return "Olá " + name + ", existe uma tarefa pendente para o grupo " +
            context.groupLabel + " do qual você faz parte. Favor verificar.";
    }

    return "Olá " + name + ", existe uma tarefa pendente sob sua responsabilidade. Favor verificar.";
}

function datasetRows(datasetName, field, value) {
    var constraint = DatasetFactory.createConstraint(field, value, value, ConstraintType.MUST);
    var dataset = DatasetFactory.getDataset(datasetName, null, [constraint], null);
    var rows = [];

    if (!dataset || !dataset.rowsCount) {
        return rows;
    }

    for (var i = 0; i < dataset.rowsCount; i++) {
        rows.push(function (row) {
            return function (column) {
                return datasetValue(dataset, row, column);
            };
        }(i));
    }

    return rows;
}

function cardValue(field) {
    try {
        return text(hAPI.getCardValue(field));
    } catch (e) {
        return "";
    }
}

function datasetValue(dataset, row, column) {
    try {
        return text(dataset.getValue(row, column));
    } catch (e) {
        return "";
    }
}

function text(value) {
    return value === null || value === undefined ? "" : String(value).trim();
}

function escapeHtml(value) {
    return text(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");
}
